}

SELECT ?person ?height WHERE  {
  ?person <is-a> <Scientist> .
  ?person <Height> ?height .
  FILTER(?height > 1.8)
}

SELECT ?person ?height WHERE  {
  ?person <is-a> <Scientist> .
  ?person <Height> ?height .
  FILTER(?height < 1.47)
}

PREFIX pathSearch: <https://qlever.cs.uni-freiburg.de/pathSearch/>
