  SERVICE pathSearch: {
    pathSearch: pathSearch:algorithm pathSearch:allPaths;
	            pathSearch:source <Mary_Ann_Leeper>;
				pathSearch:target <Literature_Subject>;
				pathSearch:pathColumn ?path;
				pathSearch:edgeColumn ?edge;
