SELECT (AVG(?x + ?y) as ?avg) WHERE {
  VALUES (?x ?y) { (0.5 1.5) (0.5 3.5) (1.2 2.8)}
} GROUP BY ?x
  ORDER BY (- SUM(?y))

SELECT (AVG(?x + ?y) as ?avg) (?avg + COUNT(?y) * 0.5 AS ?b) WHERE {
  VALUES (?x ?y) { (0.5 1.5) (0.5 3.5) (1.2 2.8)}
} GROUP BY ?x

